    (bs + SZ_BS <= schedb \/ schedb + NEWSZ_SCH <= bs) -> (bs + SZ_BS <= cfgb \/ cfgb + NEWSZ_CFG <= bs) -> (bs + SZ_BS <= allocb \/ allocb + SZ_ALLOCIMPL <= bs) ->
